// Generated by philote from page /authors. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readAuthorCard } from "@/lib/reads";

import AuthorCard from "@/components/common/author-card";

export const metadata: Metadata = { title: "Authors" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <h1 className="mx-auto w-full max-w-5xl px-4 pt-8 font-heading text-3xl font-semibold tracking-tight sm:px-6">{"Authors"}</h1>
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.authors.list());
    const props1 = await Promise.all(loaded.map(readAuthorCard));
    return (
        <>
            {props1.length === 0 ? (
                <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No authors yet."}</p>
            ) : (
                <section className="mx-auto grid w-full max-w-5xl gap-6 px-4 pt-4 pb-8 sm:grid-cols-2 sm:px-6 lg:grid-cols-3 has-[>[data-shape=row]]:max-w-3xl has-[>[data-shape=row]]:grid-cols-1 has-[>[data-shape=row]]:gap-4">
                    {props1.map((item) => (
                        <AuthorCard key={item.author.id} {...item} />
                    ))}
                </section>
            )}
        </>
    );
}
